SCENE {"title":"The Unstrung Loom","mood":"an empty loom in the dark, waiting","note":"The market has just opened and nothing came before it, so the week begins as a bare warp-weighted loom with slack threads and no cloth. Every trade is woven in. Whatever hangs from the beam on Sunday is everything that happened.","horizon":600,"celestial":{"x":300,"y":80},"anchors":{"beam":{"x":300,"y":76}},"glitch":{"smear":"=Math.min(0.4,0.05+volatility*0.3)","sort":"=Math.min(0.5,0.1+Math.log(1+fills)*0.05)","invert":0.05,"snow":"=Math.max(0.05,0.35-progress*0.3)","rupture":"=Math.min(0.3,volatility*0.3)","freeze":"=Math.max(0.1,0.6-progress*0.5)","tear":"=Math.min(0.35,Math.log(1+churn)*0.05)","drips":"=Math.min(0.4,0.05+Math.log(1+fills)*0.04)","vertical":true},"rationale":[{"factor":"theme","value":"none","effect":"No previous week exists, so the world is a dark room holding one bare loom: a beam, two uprights and loose threads with nothing woven. A faint mist sits on the floor. This is a picture of waiting, and there is no earlier week to compare it with."},{"factor":"fills","value":"{fills}","effect":"Each fill lengthens the cloth hanging down from the beam, on a log scale. At zero there is no cloth. At a few thousand fills it reaches most of the way to the weights."},{"factor":"wallets","value":"{wallets}","effect":"Sets how many warp threads hang from the beam, from 10 up to 48. One thread is pulled straight by a dark stone weight for each wallet. The rest stay slack and curl in the air."},{"factor":"churn","value":"{churn}","effect":"Sets how fast the shuttle runs back and forth along the lowest woven row, trailing its thread. It also adds a little horizontal tearing."},{"factor":"volatility","value":"{volatility}","effect":"Some woven rows come out misdyed and shoved sideways. The hanging threads and weights swing harder as it rises."},{"factor":"day","value":"day {day}, progress {progress}","effect":"The shuttle starts moving on day 2 once the first fill exists. A basket of yarn appears on the floor from day 3. The frozen, snowy static of the empty opening thaws as the week goes on."}]}
LAYER sky {"top":0.02,"hor":0.05}
LAYER paint {"ramp":"far","alpha":1,"occlude":true}
<<<draw
g.fillStyle=u.gray(0.16); g.fillRect(64,40,16,560); g.fillRect(520,40,16,560);
g.fillStyle=u.gray(0.3); g.fillRect(44,66,512,22);
g.fillStyle=u.gray(0.5); g.fillRect(44,66,512,3);
g.fillStyle=u.gray(0.26); g.fillRect(58,36,28,10); g.fillRect(514,36,28,10);
for(var i=0;i<6;i++){ u.blob(g,96+i*81,77,4,0.42); }
u.line(g,80,300,96,300,0.2,3); u.line(g,504,300,520,300,0.2,3);
for(var y=556;y<600;y+=4){ g.fillStyle=u.gray(0.03+(y-556)/44*0.07); g.fillRect(0,y,600,4); }
>>>
LAYER band {"y":578,"thick":30,"speed":2,"lum":0.2,"ramp":"fog","alpha":0.35}
LAYER live {"n":"=Math.round(Math.min(48,Math.max(10,10+Math.log(1+wallets)*7)))","weighted":"=Math.min(48,wallets)","clothH":"=Math.min(380,Math.log(1+fills)*55)","sway":"=Math.min(1,volatility)"}
<<<draw
var n=Math.max(2,Math.min(48,u.args.n|0)), top=88+(u.args.clothH||0), sw=u.args.sway||0, w=Math.max(0,Math.round(u.args.weighted||0));
g.lineCap='round';
for(var i=0;i<n;i++){
  var x=96+i*408/(n-1), ph=t*0.0009+i*0.83;
  var heavy=((i*29)%n)<w;
  if(heavy){
    var endY=505+(i%3)*12, dx=Math.sin(ph)*(1+sw*7);
    g.strokeStyle=u.rgb(u.P.light,0.5); g.lineWidth=1;
    g.beginPath(); g.moveTo(x,top); g.quadraticCurveTo(x+dx*0.3,(top+endY)/2,x+dx,endY); g.stroke();
    g.fillStyle='rgb(2,2,6)'; g.beginPath(); g.ellipse(x+dx,endY+9,6,9,dx*0.03,0,6.2832); g.fill();
    g.strokeStyle=u.rgb(u.P.hot,0.55); g.lineWidth=1; g.beginPath(); g.ellipse(x+dx,endY+9,6,9,dx*0.03,3.6,5.8); g.stroke();
  } else {
    var len=50+((i*13)%5)*18, cd=Math.sin(ph*0.6)*(8+sw*10);
    g.strokeStyle=u.rgb(u.P.light,0.22); g.lineWidth=1;
    g.beginPath(); g.moveTo(x,top); g.bezierCurveTo(x+cd*0.2,top+len*0.4,x+cd,top+len*0.7,x+cd*0.6,top+len); g.stroke();
  }
}
>>>
LAYER live {"n":"=Math.round(Math.min(48,Math.max(10,10+Math.log(1+wallets)*7)))","clothH":"=Math.min(380,Math.log(1+fills)*55)","vol":"=Math.min(1,volatility)"}
<<<draw
var H=u.args.clothH||0; if(H<2) return;
var n=Math.max(2,Math.min(48,u.args.n|0)), v=u.args.vol||0, step=408/(n-1);
var rows=Math.min(70,Math.floor(H/6)), sx=Math.sin(t*0.0005)*v*2;
for(var r=0;r<rows;r++){
  var y=88+r*6, hsh=Math.abs(Math.sin(r*12.9898)*43758.5)%1;
  var bad=hsh<v*0.25, off=bad?(hsh*40-8):0;
  var k=Math.sin(r*0.35)>0.55?0.7:0.15;
  var col=bad?u.P.star:u.mix(u.P.light,u.P.hot,k);
  var a=(r===rows-1)?0.85:0.55;
  g.fillStyle=u.rgb(col,a); g.fillRect(94+sx+off,y,412,5);
  g.fillStyle='rgba(2,2,6,0.75)'; g.beginPath();
  for(var i=(r%2);i<n;i+=2){ g.rect(96+i*step-1+sx+off,y,2.5,5); }
  g.fill();
}
>>>
LAYER live {"if":"=day>=2 && fills>0","clothH":"=Math.min(380,Math.log(1+fills)*55)","speed":"=Math.min(0.003,0.0004+Math.log(1+churn)*0.0004)"}
<<<draw
var y=88+(u.args.clothH||0)+3, sp=u.args.speed||0.0005;
var x=300+Math.sin(t*sp)*215, dir=Math.cos(t*sp)>0?1:-1;
g.strokeStyle=u.rgb(u.P.hot,0.7); g.lineWidth=1;
g.beginPath(); g.moveTo(dir>0?94:506,y); g.lineTo(x,y); g.stroke();
g.fillStyle='rgb(2,2,6)'; g.beginPath();
g.moveTo(x-20,y); g.quadraticCurveTo(x,y-7,x+20,y); g.quadraticCurveTo(x,y+7,x-20,y); g.fill();
g.strokeStyle=u.rgb(u.P.hot,0.6); g.beginPath(); g.moveTo(x-18,y-1); g.quadraticCurveTo(x,y-7,x+18,y-1); g.stroke();
>>>
LAYER paint {"if":"=day>=3 && fills>0","ramp":"near","alpha":1,"occlude":true}
<<<draw
u.poly(g,[8,552,58,552,52,592,14,592],0.18);
for(var k=0;k<4;k++){ u.line(g,10,560+k*8,56,560+k*8,0.28,1); }
u.blob(g,22,548,9,0.5); u.blob(g,40,546,8,0.38); u.blob(g,31,540,7,0.6);
u.line(g,40,546,70,594,0.35,1);
>>>
